const startDate = $now.minus({ days: 2 }).toFormat('yyyy-LL-dd');
const endDate = $now.toFormat('yyyy-LL-dd');

// CME records carry links to flare records, but not always the flare class itself.
// Fetch the same two-day flare window so alerts can use the familiar C/M/X scale.
let flares = [];
try {
  const response = await $helpers.httpRequest({
    method: 'GET',
    url: 'https://kauai.ccmc.gsfc.nasa.gov/DONKI/WS/get/FLR',
    qs: { startDate, endDate },
    json: true,
    timeout: 30000,
  });
  flares = Array.isArray(response) ? response : [];
} catch (error) {
  // An Earth-directed CME is still worth alerting on if DONKI's flare feed is late.
  console.warn(`Could not retrieve DONKI flare classes: ${error.message}`);
}

const flaresById = new Map(flares.map((flare) => [flare.flrID, flare]));
const now = Date.now();

function toMillis(value) {
  if (!value) return null;
  const millis = Date.parse(value);
  return Number.isNaN(millis) ? null : millis;
}

function formatInBrisbane(value) {
  return new Intl.DateTimeFormat('en-AU', {
    timeZone: 'Australia/Brisbane',
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
    timeZoneName: 'short',
  }).format(value);
}

function findEarthForecast(cme) {
  const forecasts = [];
  for (const analysis of cme.cmeAnalyses ?? []) {
    for (const run of analysis.enlilList ?? []) {
      const earthImpact = (run.impactList ?? []).find((impact) =>
        String(impact.location ?? '').trim().toLowerCase() === 'earth',
      );
      const directedAtEarth = run.isEarthGB === true || run.isEarthMinorImpact === true || Boolean(earthImpact);
      if (directedAtEarth) {
        forecasts.push({
          analysis,
          run,
          arrival: run.estimatedShockArrivalTime ?? earthImpact?.arrivalTime ?? null,
          glancing: run.isEarthGB === true || earthImpact?.isGlancingBlow === true,
        });
      }
    }
  }

  // Prefer DONKI's most recently completed model run when it has an Earth-impact prediction.
  return forecasts.sort((a, b) =>
    (toMillis(b.run.modelCompletionTime) ?? 0) - (toMillis(a.run.modelCompletionTime) ?? 0),
  )[0];
}

function flareFor(cme) {
  const flareLink = (cme.linkedEvents ?? []).find((event) =>
    String(event.activityID ?? '').includes('-FLR-'),
  );
  return flareLink ? flaresById.get(flareLink.activityID) : undefined;
}

function arrivalText(arrival) {
  const when = toMillis(arrival);
  if (!when) return 'A timing estimate has not been published yet.';

  const hours = Math.max(0, Math.round((when - now) / 3_600_000));
  const arrivalInBrisbane = formatInBrisbane(new Date(when));
  if (when >= now) return `About ${hours} hours (${arrivalInBrisbane}).`;
  return `The forecast time was about ${Math.abs(Math.round((when - now) / 3_600_000))} hours ago (${arrivalInBrisbane}).`;
}

return $input.all()
  .map((item) => item.json)
  .filter((cme) => cme?.activityID)
  .map((cme) => ({ cme, forecast: findEarthForecast(cme) }))
  .filter(({ forecast }) => forecast)
  .map(({ cme, forecast }) => {
    const flare = flareFor(cme);
    const intensity = flare?.classType ?? 'Not reported';
    const arrival = forecast.arrival;
    const reportUrl = cme.link ?? forecast.analysis.link ?? forecast.run.link;
    const impactDescription = forecast.glancing
      ? 'A glancing solar eruption is forecast to brush past Earth.'
      : 'A solar eruption is forecast to affect Earth’s space environment.';

    const message = [
      '☀️ **Earth-directed solar eruption**',
      '',
      impactDescription,
      `Solar flare intensity: **${intensity}**`,
      `Estimated Earth arrival: **${arrivalText(arrival)}**`,
      '',
      '_This is a space-weather forecast, not a ground-level impact forecast._',
      reportUrl ? `[Read the full DONKI observation](${reportUrl})` : null,
    ].filter(Boolean).join('\n');

    return {
      json: {
        cme_id: cme.activityID,
        first_seen_at: new Date().toISOString(),
        arrival_at: arrival,
        intensity,
        observation_url: reportUrl,
        message,
        matrix_request_id: `donki-cme-${cme.activityID}`,
      },
    };
  });

const now = Date.now();
const state = $getWorkflowStaticData('global');
const previousSwpcPoll = Date.parse(state.lastSwpcPoll ?? '');

let swpcAlerts = [];
let swpcAvailable = false;
try {
  const response = await $helpers.httpRequest({
    method: 'GET',
    url: 'https://services.swpc.noaa.gov/products/alerts.json',
    json: true,
    timeout: 30000,
  });
  swpcAlerts = Array.isArray(response) ? response : [];
  swpcAvailable = true;
} catch (error) {
  console.warn('Could not retrieve NOAA SWPC alerts: ' + error.message);
}
if (swpcAvailable) state.lastSwpcPoll = new Date(now).toISOString();

function toMillis(value) {
  const result = Date.parse(value ?? '');
  return Number.isNaN(result) ? null : result;
}

function brisbaneTime(value) {
  return new Intl.DateTimeFormat('en-AU', {
    timeZone: 'Australia/Brisbane', day: '2-digit', month: 'short',
    hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short',
  }).format(new Date(value));
}

function earthForecast(cme) {
  const matches = [];
  for (const analysis of cme.cmeAnalyses ?? []) {
    for (const run of analysis.enlilList ?? []) {
      const impact = (run.impactList ?? []).find((item) =>
        String(item.location ?? '').trim().toLowerCase() === 'earth',
      );
      if (run.isEarthGB === true || run.isEarthMinorImpact === true || impact) {
        matches.push({ run, analysis, arrival: run.estimatedShockArrivalTime ?? impact?.arrivalTime ?? null });
      }
    }
  }
  return matches.sort((a, b) => (toMillis(b.run.modelCompletionTime) ?? 0) - (toMillis(a.run.modelCompletionTime) ?? 0))[0];
}

function number(value) {
  return typeof value === 'number' ? value : null;
}

function eta(arrival) {
  const when = toMillis(arrival);
  if (!when) return 'Timing has not been published.';
  const hours = Math.max(0, Math.round((when - now) / 3600000));
  return when >= now ? '~' + hours + ' h — ' + brisbaneTime(when) : 'Forecast time passed — ' + brisbaneTime(when);
}

function report(id, intensity, arrival, url, message) {
  return {
    cme_id: id,
    first_seen_at: new Date(now).toISOString(),
    arrival_at: arrival,
    intensity,
    observation_url: url,
    message,
    matrix_request_id: 'space-weather-' + id,
  };
}

const cmeReports = $input.all()
  .map((item) => item.json)
  .filter((cme) => cme?.activityID)
  .map((cme) => ({ cme, forecast: earthForecast(cme) }))
  .filter(({ forecast }) => number(forecast.run.kp_135) >= 6)
  .map(({ cme, forecast }) => {
    const adverseKp = number(forecast.run.kp_180) ?? number(forecast.run.kp_135);
    const strong = adverseKp >= 7;
    const level = strong ? 'possible G3 strong storm' : 'possible G2 moderate storm';
    const effects = strong
      ? 'Expect possible intermittent HF/GPS disruption and satellite effects.'
      : 'Expect possible HF fading and satellite effects, mainly at high latitudes.';
    const url = cme.link ?? forecast.analysis.link ?? forecast.run.link;
    return report(
      cme.activityID,
      strong ? 'G3 possible' : 'G2 possible',
      forecast.arrival,
      url,
      ['🧲 **CME ARRIVAL — ' + level + '**', 'ETA: **' + eta(forecast.arrival) + '**', effects, url ? '[Forecast](' + url + ')' : null].filter(Boolean).join('\n'),
    );
  });

function issueMillis(alert) {
  const value = String(alert.issue_datetime ?? '').trim().replace(' ', 'T');
  return toMillis(value ? value + 'Z' : '');
}

function swpcReport(alert) {
  const message = String(alert.message ?? '');
  const scale = message.match(/Noaa Scale:\s*([RS][1-5])\s*-\s*([A-Za-z]+)/i);
  const serial = message.match(/Serial Number:\s*(\d+)/i);
  if (!scale || !serial || !/^(ALERT|WARNING):/m.test(message)) return null;
  if (!Number.isFinite(previousSwpcPoll) || (issueMillis(alert) ?? 0) <= previousSwpcPoll - 60000) return null;

  const level = scale[1].toUpperCase() + ' ' + scale[2];
  const radiation = scale[1].toUpperCase().startsWith('S');
  const title = radiation ? '☢️ **PARTICLE STORM — ' + level + '**' : '☀️ **SOLAR FLARE — ' + level + '**';
  const effects = radiation
    ? 'Polar HF and satellite radiation impacts may be underway.'
    : 'HF radio disruption may be underway on Earth’s sunlit side.';
  const id = 'swpc-' + String(alert.product_id ?? 'alert') + '-' + serial[1];
  return report(
    id,
    level,
    new Date(issueMillis(alert) ?? now).toISOString(),
    'https://www.swpc.noaa.gov/products/alerts',
    [title, effects, '[Details](https://www.swpc.noaa.gov/products/alerts)'].join('\n'),
  );
}

const swpcReports = swpcAvailable ? swpcAlerts.map(swpcReport).filter(Boolean) : [];
return [...cmeReports, ...swpcReports].map((json) => ({ json, pairedItem: { item: 0 } }));

const alert = $input.item.json;

return [{
  json: {
    ...alert,
    message: String(alert.message ?? '').replace(/\n+/g, '\n\n'),
  },
  pairedItem: { item: 0 },
}];

const alert = $input.item.json;
const intensity = String(alert.intensity ?? '');

function reportedAt(value) {
  const when = Date.parse(value ?? '');
  if (Number.isNaN(when)) return 'just now';
  return new Intl.DateTimeFormat('en-AU', {
    timeZone: 'Australia/Brisbane', day: '2-digit', month: 'short',
    hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short',
  }).format(new Date(when));
}

const sections = String(alert.message ?? '').split('\n\n');
if (intensity.startsWith('R')) {
  sections.splice(1, 0, 'Reported: **' + reportedAt(alert.arrival_at) + '**', 'Status: **already underway** — Sun–Earth light time is ~8 min.');
} else if (intensity.startsWith('S')) {
  sections.splice(1, 0, 'Reported: **' + reportedAt(alert.arrival_at) + '**', 'Status: **may already be underway** — particle travel time is not fixed.');
}

return [{
  json: { ...alert, message: sections.join('\n\n') },
  pairedItem: { item: 0 },
}];

const alert = $input.item.json;
const scaleUrl = 'https://www.swpc.noaa.gov/node/1085';
let message = String(alert.message ?? '').replace(/\n\n\[Forecast\]\([^)]*\)$/, '');

if (String(alert.intensity ?? '').startsWith('G') && alert.observation_url) {
  message += '\n\n[DONKI CME observation](' + alert.observation_url + ')';
}
message += '\n\n[NOAA scale definitions](' + scaleUrl + ')';

return [{
  json: { ...alert, message },
  pairedItem: { item: 0 },
}];

const report = $('Prepare concise space weather alerts').item.json;

return {
  json: {
    cme_id: report.cme_id,
    first_seen_at: report.first_seen_at,
    arrival_at: report.arrival_at,
    intensity: report.intensity,
    observation_url: report.observation_url,
    matrix_event_id: $json.event_id ?? null,
  },
};
